import java.util.*;
import java.io.*;

public class Main {
    static final int MAXN = 110;
    static final int MOD = 1000000007;
    static int[][] com = new int[MAXN + 1][MAXN + 1];

    public static void makeCom() {
        for (int i = 0; i <= MAXN; i++) {
            com[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                com[i][j] = (com[i - 1][j - 1] + com[i - 1][j]) % MOD;
            }
        }
    }

    public static List<long[]> readIn(BufferedReader br) throws IOException {
        List<long[]> result = new ArrayList<>();
        String inputStr = br.readLine();
        if (inputStr == null) {
            return result;
        }
        String[] dataStr = inputStr.trim().split("\\s+");
        int offset = 0;
        int length = dataStr.length;
        while (offset < length) {
            int n = Integer.parseInt(dataStr[offset]);
            int cap = Integer.parseInt(dataStr[offset + 1]);
            offset += 2;
            long[] friendsCount = new long[2]; // total counts of friends in each group
            for (int i = 0; i < n; i++) {
                int x = Integer.parseInt(dataStr[offset + i]);
                if (x / 50 - 1 >= 0 && x / 50 - 1 < 2) {
                    friendsCount[x / 50 - 1]++;
                }
            }
            offset += n;
            long capVal = cap / 50;
            result.add(new long[]{capVal, friendsCount[0], friendsCount[1]});
        }
        return result;
    }

    public static void solve(long cap, long[] friends) {
        Map<List<Long>, Long> f = new HashMap<>();
        List<Long> friendsList = Arrays.asList(friends[0], friends[1]);
        f.put(friendsList, 1L);
        long totalFriends = friends[0] + friends[1];

        for (long rides = 0; rides <= totalFriends * 5; rides++) {
            if ((rides & 1) == 1 && f.containsKey(friendsList)) {
                System.out.println(rides);
                System.out.println(f.get(friendsList));
                return;
            }
            Map<List<Long>, Long> pf = f;
            f = new HashMap<>();
            for (Map.Entry<List<Long>, Long> entry : pf.entrySet()) {
                List<Long> remain = entry.getKey();
                long count = entry.getValue();

                for (int x = 0; x <= remain.get(0); x++) {
                    if (x > cap) break;
                    for (int y = 0; y <= remain.get(1); y++) {
                        if (x + y < 1) continue;
                        if (x + 2 * y > cap) break;

                        long nextRem0 = friends[0] - remain.get(0) + x;
                        long nextRem1 = friends[1] - remain.get(1) + y;
                        List<Long> nextRem = Arrays.asList(nextRem0, nextRem1);

                        long waysX = com[(int) remain.get(0)][x];
                        long waysY = com[(int) remain.get(1)][y];

                        long newCount = (f.getOrDefault(nextRem, 0L) + waysX * waysY * count) % MOD;
                        f.put(nextRem, newCount);
                    }
                }
            }
        }
        System.out.println(-1);
        System.out.println(0);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        makeCom();
        List<long[]> inputData = readIn(br);
        for (long[] data : inputData) {
            long cap = data[0];
            long[] friends = {data[1], data[2]};
            solve(cap, friends);
        }
    }
}
